queue action resurrect-target:
            with:
                @healer: @healer
                @corpse: @corpse
            urgent: true

queue action gain-xp:
            with partial:
                @hero: @killer
                @victim: @who
            urgent: true
            abandon: @killer.role != #PLAYER

queue action take-damage:
            with partial:
                @victim: @target
                @source: @attacker
            urgent: true

queue action tick-corpse-run:
            with partial:
                @who: @who
            time: after: 1 minute from action
            repeat:
                if:
                    @who.alive == false
                max: 3

queue action take-damage:
            with partial:
                @victim: @target
                @source: @attacker
            urgent: true

queue action die:
            with partial:
                @who: @victim
                @killer: @source
            urgent: true
            abandon: @victim.hp > 0
        queue action retaliate:
            with partial:
                @attacker: @victim
                @target: @source
            urgent: true
            abandon: @victim.alive == false

